s=s.replace('''/// Where messages go''','''/// Largest visibility timeout, in seconds, for a queue or a single receive.
pub const MAX_VISIBILITY_TIMEOUT: u64 = 43_200;
/// Largest delay, in seconds, for a queue or a single message.
pub const MAX_DELAY_SECONDS: u64 = 900;

/// Where messages go''',1)
s=s.replace('0..=43_200','0..=MAX_VISIBILITY_TIMEOUT').replace('0..=900','0..=MAX_DELAY_SECONDS')
s=s.replace('''    /// The dead-letter configuration, which''','''    /// Rejects `ContentBasedDeduplication: true` on a queue that is not FIFO.
    pub fn check_deduplication_needs_fifo(&self, fifo: bool) -> Result<()> {
        if self.content_based_deduplication == Some(true) && !fifo {
            return Err(Error::new(
                ErrorCode::InvalidParameterValue,
                "`ContentBasedDeduplication` requires a FIFO queue",
            ));
        }
        Ok(())
    }

    /// The dead-letter configuration, which''')
open(p,'w').write(s)
p='src/broker/queue_commands.rs'; s=open(p).read()
old='''        if update.content_based_deduplication == Some(true) && !fifo {
            return Err(invalid_value(
                "`ContentBasedDeduplication` requires a FIFO queue",
            ));
        }
'''
assert s.count(old)==2
s=s.replace(old,'        update.check_deduplication_needs_fifo(fifo)?;\n')
open(p,'w').write(s)
p='src/broker/message_commands.rs'; s=open(p).read()
s=s.replace('0..=900','0..=MAX_DELAY_SECONDS').replace('0..=43_200','0..=MAX_VISIBILITY_TIMEOUT')
s=s.replace('use crate::error','use crate::attributes::{MAX_DELAY_SECONDS, MAX_VISIBILITY_TIMEOUT};\nuse crate::error',1)
s=s.replace('plan_receive(now, max_messages as usize)','plan_receive(now, max_messages)')
open(p,'w').write(s)
p='src/queue.rs'; s=open(p).read()
s=s.replace('max_messages: usize','max_messages: u64')
open(p,'w').write(s)
E
